with gaps as (select *, case when lag(reading_ts) over (partition by device_code order by reading_ts, id) is null or reading_ts > lag(reading_ts) over (partition by device_code order by reading_ts, id) + interval '1' hour then 1 else 0 end as is_new_session from device_readings), sessions_device_readings as (select *, sum(is_new_session) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as session_no from gaps) select date_trunc('hour', reading_ts) as hour_window, size(collect_set(device_code)) as num_device_codes, sort_array(collect_set(device_code)) as device_code_list, count(*) filter (where device_code = 'DV-03') as dv_03_rows, sort_array(collect_set(device_code)) as device_code_list_2, approx_percentile(temp_c, array(0.25, 0.5, 0.75)) as temp_c_quartiles, avg(session_no) as avg_session_no from sessions_device_readings group by hour_window
